function findOrder(numCourses, prerequisites) {
  const adj = Array.from({ length: numCourses }, () => []);
  const indeg = new Array(numCourses).fill(0);
  for (const [a, b] of prerequisites) { adj[b].push(a); indeg[a]++; }
  // min-heap of available courses
  const h = [];
  const push = (x) => { h.push(x); let i = h.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (h[p] <= h[i]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
  const pop = () => {
    const top = h[0], last = h.pop();
    if (h.length) { h[0] = last; let i = 0; for (;;) { const l = 2*i+1, r = l+1; let s = i; if (l < h.length && h[l] < h[s]) s = l; if (r < h.length && h[r] < h[s]) s = r; if (s === i) break; [h[s], h[i]] = [h[i], h[s]]; i = s; } }
    return top;
  };
  for (let i = 0; i < numCourses; i++) if (indeg[i] === 0) push(i);
  const order = [];
  while (h.length) {
    const c = pop();
    order.push(c);
    for (const nxt of adj[c]) if (--indeg[nxt] === 0) push(nxt);
  }
  return order.length === numCourses ? order : [];
}

