import java.util.function.LongSupplier;

class TokenBucket {
  private final int capacity;
  private final double rate;
  private final LongSupplier clock;
  private double tokens;
  private long last;

  public TokenBucket(int capacity, double refillPerSecond, LongSupplier clock) {
    this.capacity = capacity;
    this.rate = refillPerSecond;
    this.clock = clock;
    this.tokens = capacity;
    this.last = clock.getAsLong();
  }

  private void refill() {
    long now = clock.getAsLong();
    long elapsed = Math.max(0, now - last);
    tokens = Math.min(capacity, tokens + elapsed / 1000.0 * rate);
    last = now;
  }

  public synchronized boolean tryAcquire() { return tryAcquire(1); }

  public synchronized boolean tryAcquire(int n) {
    refill();
    if (tokens >= n) { tokens -= n; return true; }
    return false;
  }
}

