class Solution {
  public long[] backoffSchedule(long baseMs, long maxMs, int attempts, DoubleSupplier rand) {
    long[] out = new long[attempts];
    long cap = Math.min(baseMs, maxMs);
    for (int i = 0; i < attempts; i++) {
      out[i] = rand == null ? cap : (long) Math.floor(rand.getAsDouble() * cap);
      cap = cap >= maxMs / 2 ? maxMs : cap * 2;
    }
    return out;
  }
}

