class Autocomplete {
  constructor() { this.root = { children: new Map(), end: false }; }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), end: false });
      node = node.children.get(ch);
    }
    node.end = true;
  }
  suggest(prefix, k) {
    let node = this.root;
    for (const ch of prefix) {
      node = node.children.get(ch);
      if (!node) return [];
    }
    const out = [];
    const dfs = (n, path) => {
      if (out.length >= k) return;
      if (n.end) out.push(path);
      const keys = [...n.children.keys()].sort();
      for (const c of keys) { if (out.length >= k) return; dfs(n.children.get(c), path + c); }
    };
    dfs(node, prefix);
    return out;
  }
}

