import java.util.*;

class Autocomplete {
  private static class Node { TreeMap<Character, Node> children = new TreeMap<>(); boolean end; }
  private final Node root = new Node();

  public void insert(String word) {
    Node n = root;
    for (char c : word.toCharArray()) n = n.children.computeIfAbsent(c, x -> new Node());
    n.end = true;
  }

  public List<String> suggest(String prefix, int k) {
    Node n = root;
    for (char c : prefix.toCharArray()) {
      n = n.children.get(c);
      if (n == null) return new ArrayList<>();
    }
    List<String> out = new ArrayList<>();
    dfs(n, new StringBuilder(prefix), k, out);
    return out;
  }

  private void dfs(Node n, StringBuilder path, int k, List<String> out) {
    if (out.size() >= k) return;
    if (n.end) out.add(path.toString());
    for (Map.Entry<Character, Node> e : n.children.entrySet()) {
      if (out.size() >= k) return;
      path.append(e.getKey());
      dfs(e.getValue(), path, k, out);
      path.deleteCharAt(path.length() - 1);
    }
  }
}

