import java.util.*;

class NestedIterator {
  private final Deque<Iterator<Object>> stack = new ArrayDeque<>();
  private Integer peeked;

  public NestedIterator(List<Object> nestedList) { stack.push(nestedList.iterator()); }

  @SuppressWarnings("unchecked")
  public boolean hasNext() {
    while (peeked == null && !stack.isEmpty()) {
      Iterator<Object> it = stack.peek();
      if (!it.hasNext()) { stack.pop(); continue; }
      Object o = it.next();
      if (o instanceof Integer i) peeked = i;
      else stack.push(((List<Object>) o).iterator());
    }
    return peeked != null;
  }

  public int next() {
    if (!hasNext()) throw new NoSuchElementException();
    int v = peeked;
    peeked = null;
    return v;
  }
}

