class ConsistentHashRing {
  constructor(vnodes) {
    this.vnodes = vnodes;
    this.points = []; // sorted [hash, node]
  }
  _lowerBound(h) {
    let lo = 0, hi = this.points.length;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (this.points[mid][0] < h) lo = mid + 1; else hi = mid; }
    return lo;
  }
  addNode(name) {
    for (let i = 0; i < this.vnodes; i++) {
      const h = fnv1a(name + '#' + i);
      const idx = this._lowerBound(h);
      if (idx < this.points.length && this.points[idx][0] === h) continue; // collision: first wins
      this.points.splice(idx, 0, [h, name]);
    }
  }
  removeNode(name) {
    this.points = this.points.filter(p => p[1] !== name);
  }
  getNode(key) {
    if (!this.points.length) return null;
    let idx = this._lowerBound(fnv1a(key));
    if (idx === this.points.length) idx = 0;
    return this.points[idx][1];
  }
}

