import java.util.*;

class ConsistentHashRing {
  static long fnv1a(String s) {
    int h = 0x811c9dc5;
    for (int i = 0; i < s.length(); i++) { h ^= s.charAt(i); h *= 0x01000193; }
    return Integer.toUnsignedLong(h);
  }

  private final int vnodes;
  private final TreeMap<Long, String> ring = new TreeMap<>();

  public ConsistentHashRing(int vnodes) { this.vnodes = vnodes; }

  public void addNode(String name) {
    for (int i = 0; i < vnodes; i++) ring.putIfAbsent(fnv1a(name + "#" + i), name);
  }

  public void removeNode(String name) {
    ring.values().removeIf(n -> n.equals(name));
  }

  public String getNode(String key) {
    if (ring.isEmpty()) return null;
    Map.Entry<Long, String> e = ring.ceilingEntry(fnv1a(key));
    if (e == null) e = ring.firstEntry();
    return e.getValue();
  }
}

