function mergeKSorted(lists) {
  const h = []; // [value, listIdx, elemIdx]
  const less = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1]);
  const push = (x) => { h.push(x); let i = h.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (!less(h[i], h[p])) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
  const pop = () => {
    const top = h[0], last = h.pop();
    if (h.length) { h[0] = last; let i = 0; for (;;) { const l = 2*i+1, r = l+1; let s = i; if (l < h.length && less(h[l], h[s])) s = l; if (r < h.length && less(h[r], h[s])) s = r; if (s === i) break; [h[s], h[i]] = [h[i], h[s]]; i = s; } }
    return top;
  };
  lists.forEach((l, i) => { if (l.length) push([l[0], i, 0]); });
  const out = [];
  while (h.length) {
    const [v, li, ei] = pop();
    out.push(v);
    if (ei + 1 < lists[li].length) push([lists[li][ei + 1], li, ei + 1]);
  }
  return out;
}

