class Solution {
  public int[] mergeKSorted(int[][] lists) {
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
    int total = 0;
    for (int i = 0; i < lists.length; i++) {
      total += lists[i].length;
      if (lists[i].length > 0) heap.offer(new int[]{lists[i][0], i, 0});
    }
    int[] out = new int[total];
    int n = 0;
    while (!heap.isEmpty()) {
      int[] t = heap.poll();
      out[n++] = t[0];
      if (t[2] + 1 < lists[t[1]].length) heap.offer(new int[]{lists[t[1]][t[2] + 1], t[1], t[2] + 1});
    }
    return out;
  }
}

