      if (w === endWord) return steps;
      for (let i = 0; i < w.length; i++) {
        for (const c of letters) {
          if (c === w[i]) continue;
          const cand = w.slice(0, i) + c + w.slice(i + 1);
          if (dict.has(cand) && !seen.has(cand)) { seen.add(cand); next.push(cand); }
